CREATE SCHEMA vcm;
REVOKE ALL ON SCHEMA vcm FROM PUBLIC;
SET search_path=vcm,pg_catalog;
CREATE FUNCTION vcm.immutable_row() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable record: %',TG_TABLE_NAME USING ERRCODE='55000'; END $$;
CREATE TABLE principals(id text PRIMARY KEY CHECK(length(id)>0),kind text NOT NULL CHECK(kind IN ('human','service')),name text NOT NULL CHECK(length(trim(name))>0),active boolean NOT NULL DEFAULT true,permissions_version int NOT NULL DEFAULT 1 CHECK(permissions_version>0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,kind));
CREATE TABLE users(principal_id text PRIMARY KEY,principal_kind text NOT NULL DEFAULT 'human' CHECK(principal_kind='human'),email text NOT NULL CHECK(length(trim(email))>0),password_hash text NOT NULL,FOREIGN KEY(principal_id,principal_kind) REFERENCES principals(id,kind));
CREATE UNIQUE INDEX users_email_key ON users(lower(email));
CREATE FUNCTION normalize_email() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.email=lower(trim(NEW.email)); RETURN NEW; END $$;
CREATE TRIGGER normalize_email BEFORE INSERT OR UPDATE OF email ON users FOR EACH ROW EXECUTE FUNCTION normalize_email();
CREATE TABLE roles(code text PRIMARY KEY);
CREATE TABLE principal_roles(principal_id text NOT NULL REFERENCES users(principal_id),role_code text NOT NULL REFERENCES roles(code),PRIMARY KEY(principal_id,role_code));
CREATE TABLE sessions(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(principal_id),token_hash text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz NOT NULL DEFAULT now(),idle_expires_at timestamptz NOT NULL,max_expires_at timestamptz NOT NULL,revoked_at timestamptz,CHECK(idle_expires_at<=max_expires_at));
CREATE INDEX sessions_user_idx ON sessions(user_id);
CREATE TABLE service_credentials(id text PRIMARY KEY,principal_id text NOT NULL,principal_kind text NOT NULL DEFAULT 'service' CHECK(principal_kind='service'),token_hash text NOT NULL UNIQUE,scopes text[] NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz,revoked_at timestamptz,FOREIGN KEY(principal_id,principal_kind) REFERENCES principals(id,kind));
CREATE INDEX service_credentials_principal_idx ON service_credentials(principal_id);
CREATE TABLE protected_objects(id text PRIMARY KEY,kind text NOT NULL,confidentiality text NOT NULL DEFAULT 'internal' CHECK(confidentiality IN('internal','restricted','sensitive')),owner_id text REFERENCES principals(id),archived_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX protected_owner_idx ON protected_objects(owner_id);
CREATE TABLE object_grants(object_id text NOT NULL REFERENCES protected_objects(id),principal_id text NOT NULL REFERENCES principals(id),permission text NOT NULL CHECK(permission IN('read','write','review')),valid_from timestamptz NOT NULL DEFAULT now(),valid_until timestamptz,PRIMARY KEY(object_id,principal_id,permission),CHECK(valid_until IS NULL OR valid_until>valid_from));
CREATE INDEX grants_principal_idx ON object_grants(principal_id);
CREATE FUNCTION protect_object() RETURNS trigger LANGUAGE plpgsql SET search_path=vcm,pg_catalog AS $$ BEGIN IF NEW.protected_object_id IS NULL THEN NEW.protected_object_id=TG_ARGV[0]||':'||NEW.id; INSERT INTO protected_objects(id,kind) VALUES(NEW.protected_object_id,TG_ARGV[0]); END IF; IF NOT EXISTS(SELECT 1 FROM protected_objects WHERE id=NEW.protected_object_id AND kind=TG_ARGV[0]) THEN RAISE EXCEPTION 'Object kind mismatch' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TABLE object_revisions(id text PRIMARY KEY,object_id text NOT NULL REFERENCES protected_objects(id),version int NOT NULL CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(object_id,version),UNIQUE(object_id,id));
CREATE TRIGGER revision_immutable BEFORE UPDATE OR DELETE ON object_revisions FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE FUNCTION register_revision() RETURNS trigger LANGUAGE plpgsql SET search_path=vcm,pg_catalog AS $$ DECLARE obj text; BEGIN EXECUTE format('SELECT protected_object_id FROM vcm.%I WHERE id=$1',TG_ARGV[0]) INTO obj USING to_jsonb(NEW)->>TG_ARGV[1]; IF obj IS NULL THEN RAISE EXCEPTION 'Revision parent missing' USING ERRCODE='23503'; END IF; INSERT INTO object_revisions(id,object_id,version) VALUES(NEW.id,obj,NEW.version); RETURN NEW; END $$;
CREATE TABLE portfolios(id text PRIMARY KEY,code text NOT NULL UNIQUE,name text NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE organizations(id text PRIMARY KEY,name text NOT NULL,type text,tax_id text,email text,phone text,website text,notes text,version int NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),archived_at timestamptz);
CREATE TABLE contacts(id text PRIMARY KEY,name text NOT NULL,email text,phone text,principal_id text REFERENCES users(principal_id),version int NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),archived_at timestamptz);
CREATE TABLE organization_contacts(organization_id text NOT NULL REFERENCES organizations(id),contact_id text NOT NULL REFERENCES contacts(id),role text NOT NULL DEFAULT '',valid_from date,valid_until date,PRIMARY KEY(organization_id,contact_id,role),CHECK(valid_until IS NULL OR valid_from IS NULL OR valid_until>=valid_from));
CREATE INDEX organization_contacts_contact_idx ON organization_contacts(contact_id);
CREATE TABLE agreements(id text PRIMARY KEY,organization_id text NOT NULL REFERENCES organizations(id),responsible_contact_id text REFERENCES contacts(id),name text NOT NULL,type text,description text,starts_on date NOT NULL,ends_on date,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','active','expired','cancelled')),notes text,protected_object_id text NOT NULL UNIQUE REFERENCES protected_objects(id),version int NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_on IS NULL OR ends_on>=starts_on));
CREATE TRIGGER agreement_protect BEFORE INSERT ON agreements FOR EACH ROW EXECUTE FUNCTION protect_object('agreement');
CREATE TABLE resources(id text PRIMARY KEY,name text NOT NULL,category text NOT NULL CHECK(category IN('space','equipment','material','service')),unit text NOT NULL,quantity numeric CHECK(quantity>=0),description text,notes text,active boolean NOT NULL DEFAULT true,version int NOT NULL DEFAULT 1 CHECK(version>0));
CREATE TABLE catalog_versions(id text PRIMARY KEY,kind text NOT NULL,source text,availability text NOT NULL CHECK(availability IN('available','pending')),valid_from date,valid_until date,UNIQUE(kind,id));
CREATE TABLE catalog_entries(catalog_version_id text NOT NULL REFERENCES catalog_versions(id),code text NOT NULL,label text NOT NULL,active boolean NOT NULL DEFAULT true,PRIMARY KEY(catalog_version_id,code));
CREATE TABLE state_definitions(object_kind text NOT NULL,rule_version text NOT NULL,code text NOT NULL,label text NOT NULL,PRIMARY KEY(object_kind,rule_version,code));
CREATE TABLE transition_definitions(object_kind text NOT NULL,rule_version text NOT NULL,from_state text NOT NULL,to_state text NOT NULL,PRIMARY KEY(object_kind,rule_version,from_state,to_state),FOREIGN KEY(object_kind,rule_version,from_state) REFERENCES state_definitions,FOREIGN KEY(object_kind,rule_version,to_state) REFERENCES state_definitions);

-- Controlled source catalogs, PO September 2026.
